async def _init_tool_manager(agent_app) -> None:
    """初始化统一工具管理器（失败不阻断服务启动）。

    组装 ToolRegistry + ToolDatabase(SQLite) + ToolInstaller，
    并合并平台下发的 ~/.openchiip-harness/data/tools.json 安装记录。
    """
    try:
        from agent_runtime.core.tool_installer import build_tool_installer

        installer = build_tool_installer(agent_app)
        if installer is None:
            logger.warning('工具管理器组装失败，工具管理 API 将使用降级实例')
            return
        await installer.initialize()
        agent_app.tool_installer = installer
        logger.info('工具管理器已初始化: %d 个可管理工具', len(installer.registry))
    except Exception as e:
        logger.warning('工具管理器初始化失败: %s', e)


def _build_standalone_config():
    """从 ~/.openchiip-harness/config.yaml 构建 RuntimeConfig（独立模式）。

    通过设置环境变量让 RuntimeConfig 正确读取配置，
    因为 RuntimeConfig 从 os.environ 获取核心参数。
    """
    import yaml
    from agent_runtime.core.config import RuntimeConfig
    from agent_runtime.main import _load_agent_env

    # 先加载平台下发的 agent.env（密钥/环境变量），再构造 RuntimeConfig 以使其生效
    _load_agent_env()

    config_path = Path.home() / '.openchiip-harness' / 'config.yaml'
    if config_path.exists():
        with open(config_path) as f:
            cfg = yaml.safe_load(f) or {}
    else:
        cfg = {}

    llm_cfg = cfg.get('llm', {})
    server_cfg = cfg.get('server', {})
    storage_cfg = cfg.get('storage', {})
    platform_cfg = cfg.get('platform', {})

    agent_id = platform_cfg.get('agent_id') or os.environ.get(
        'AGENT_ID', 'standalone')

    # 设置 RuntimeConfig 实际读取的环境变量
    data_dir = Path(storage_cfg.get('data_dir',
                                    Path.home() / '.openchiip-harness' / 'data'))
    data_dir.mkdir(parents=True, exist_ok=True)

    os.environ.setdefault('AGENT_ID', agent_id)
    os.environ.setdefault('AGENT_RUNTIME_HOME', str(data_dir))
    os.environ.setdefault('MODEL_NAME',
                          llm_cfg.get('model_name', 'ernie-5.1'))
    os.environ.setdefault('FAST_MODEL_NAME',
                          llm_cfg.get('fast_model_name', 'ernie-4.5-turbo-128k'))

    # LLM API 配置
    api_key = llm_cfg.get('api_key', '')
    if api_key:
        os.environ.setdefault('LLM_API_KEY', api_key)

    # MODEL_SERVER: 根据 provider 设置默认值
    provider = llm_cfg.get('provider', 'baidu')
    model_server = llm_cfg.get('model_server', '')
    if not model_server:
        # 常用默认值
        defaults = {
            'baidu': 'https://aip.baidubce.com/rpc/2.0/ai_custom/v1/wenxinworkshop',
            'openai': 'https://api.openai.com/v1',
        }
        model_server = defaults.get(provider, '')
    if model_server:
        os.environ.setdefault('MODEL_SERVER', model_server)

    # 运行模式: 由 config.json 通过 RuntimeConfig._load_overrides() 加载
    # 不再从 config.yaml 设置 AGENT_RUN_MODE，避免双源不一致

    # 平台 WS 配置
    if platform_cfg.get('enabled'):
        ws_url = platform_cfg.get('ws_url', '')
        if ws_url:
            # 从完整 URL 提取 base URL (ws://host:port)
            # 格式: ws://host:port/ws/agent/{agent_id}/
            import re
            match = re.match(r'(wss?://[^/]+)', ws_url)
            if match:
                base_url = match.group(1)
                os.environ.setdefault('AGENT_WS_URL', base_url)

    config = RuntimeConfig(agent_id=agent_id)
    return config


def _load_platform_config():
    """从 config.yaml 加载平台配置。"""
    import yaml
    config_path = Path.home() / '.openchiip-harness' / 'config.yaml'
    if config_path.exists():
        with open(config_path) as f:
            cfg = yaml.safe_load(f) or {}
        return cfg.get('platform', {})
    return {}


def create_app() -> FastAPI:
    """创建并配置 FastAPI 应用。"""
    app = FastAPI(
        title='OpenChiip Agent Framework',
        version='0.0.30',
        description='独立 Agent 框架 — HTTP/WebSocket API',
        lifespan=lifespan,
    )

    # CORS
    app.add_middleware(
        CORSMiddleware,
        allow_origins=['*'],
        allow_credentials=True,
        allow_methods=['*'],
        allow_headers=['*'],
    )

    # 注册 API 路由
    from agent_runtime.server.api import (
        chat, sessions, skills, metaskills, tools,
        commands, a2a, memory, knowledge, config_api, monitor, status,
        capabilities, session_events, feedback, workspace, tasks,
        projects, mode, credentials, llm,
        repo_credentials,
    )
    app.include_router(chat.router, prefix='/api/v1')
    app.include_router(sessions.router, prefix='/api/v1')
    app.include_router(skills.router, prefix='/api/v1')
    app.include_router(metaskills.router, prefix='/api/v1')
    # 工具管理：统一 CLI Agent 工具（探测/安装/启停）+ 既有 MCP 工具端点
    app.include_router(tools.router, prefix='/api/v1')
    app.include_router(commands.router, prefix='/api/v1')
    app.include_router(a2a.router, prefix='/api/v1')
    app.include_router(memory.router, prefix='/api/v1')
    app.include_router(knowledge.router, prefix='/api/v1')
    app.include_router(config_api.router, prefix='/api/v1')
    app.include_router(monitor.router, prefix='/api/v1')
    app.include_router(status.router, prefix='/api/v1')
    app.include_router(feedback.router, prefix='/api/v1')
    # v3.1 新增
    app.include_router(capabilities.router, prefix='/api/v1')
    app.include_router(session_events.router, prefix='/api/v1')
    app.include_router(workspace.router, prefix='/api/v1')
    app.include_router(tasks.router, prefix='/api/v1')
    app.include_router(projects.router, prefix='/api/v1')
    app.include_router(mode.router, prefix='/api/v1')
    app.include_router(credentials.router, prefix='/api/v1')
    app.include_router(llm.router, prefix='/api/v1')
    app.include_router(repo_credentials.router, prefix='/api/v1')

    # WebSocket
    from agent_runtime.server.ws_handler import router as ws_router
    app.include_router(ws_router)

    # 静态文件服务（前端 build 产物）
    web_dist = Path(__file__).parent.parent.parent / 'web' / 'dist'
    if web_dist.exists():
        # 挂载静态资源目录（JS/CSS 等带 hash 的打包文件）
        app.mount('/assets',
                  StaticFiles(directory=str(web_dist / 'assets')),
                  name='static')

        # SPA 回退：非 API 路径均返回 index.html，由前端路由接管
        @app.get('/')
        @app.get('/{path:path}')
        async def spa_fallback(path: str = ''):
            if path.startswith('api/') or path.startswith('ws/'):
                return JSONResponse({'detail': 'Not Found'}, status_code=404)
            # 优先尝试提供 dist 下的实际文件（如 icon.ico）
            file_path = web_dist / path if path else web_dist / 'index.html'
            if file_path.is_file():
                return FileResponse(str(file_path))
            # 否则返回 index.html（SPA 客户端路由）
            return FileResponse(str(web_dist / 'index.html'))

    @app.exception_handler(Exception)
    async def global_exception_handler(request: Request, exc: Exception):
        logger.exception('未处理异常: %s', exc)
        return JSONResponse(
            status_code=500,
            content={'error': str(exc), 'type': type(exc).__name__})

    return app


def run_server(host='127.0.0.1', port=8900, **kwargs):
    """启动 uvicorn 服务器。"""
    import uvicorn
    logger.info('启动 OpenChiip Agent 服务器 %s:%d', host, port)
    uvicorn.run(
        'agent_runtime.server.app:create_app',
        host=host, port=port,
        factory=True,
        log_level='info',
        **kwargs,
    )


if __name__ == '__main__':
    run_server()
